    public static ToolDefinition SkillsDefinition = new ToolDefinition(
            "load_skill",
            "加载指定的技能（工具集合）。可用技能：" + String.join(", ", Agent05.skillLoader.getAvailableSkills()),
            createInputSchema(
                    Map.of("skill_name", createProperty("string", "要加载的技能名称")),
                    List.of("skill_name")
            ),
            LoadSkillInput.class,
            Tools::skillLoad
    );

    /**
     * 待办事项工具定义
     * 用于管理任务列表，支持添加、更新或完成任务
     */
    public static ToolDefinition TodoDefinition = new ToolDefinition(
            "todo",
            "管理待办事项列表。使用此工具可以添加、更新或完成任务。支持任务状态追踪，包括待处理、进行中和已完成三种状态。",
            createInputSchema(
                    Map.of("todos",
                            Map.of(
                                    "type", "array",
                                    "description", "待办事项列表",
                                    "items", Map.of(
                                            "type", "object",
                                            "properties", Map.of(
                                                    "id", Map.of("type", "string", "description", "任务的唯一标识符"),
                                                    "content", Map.of("type", "string", "description", "待办事项的内容描述"),
                                                    "status", Map.of(
                                                            "type", "string",
                                                            "enum", List.of("pending", "in_progress", "completed"),
                                                            "description", "任务状态：pending-待处理, in_progress-进行中, completed-已完成"
                                                    )
                                            ),
                                            "required", List.of("id", "content", "status")
                                    )
                            )
                    ),
                    List.of("todos")
            ),
            TodoInput.class,
            Agent05.todoManager::updateTodos
    );

    /**
     * 创建属性定义
     */
    public static Map<String, Object> createProperty(String type, String description) {
        Map<String, Object> property = new HashMap<>();
        property.put("type", type);
        property.put("description", description);
        return property;
    }

    /**
     * 创建InputSchema
     */
    public static Tool.InputSchema createInputSchema(Map<String, Object> properties, List<String> required) {
        ObjectNode propertiesNode = OBJECT_MAPPER.valueToTree(properties);

        Tool.InputSchema.Builder schemaBuilder = Tool.InputSchema.builder()
                .properties(JsonValue.fromJsonNode(propertiesNode));

        if (required != null && !required.isEmpty()) {
            schemaBuilder.required(required);
        }

        return schemaBuilder.build();
    }
}

package com.hoppinzq.agent.tool.manager;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.hoppinzq.agent.tool.schema.TodoInput;
import com.hoppinzq.agent.tool.schema.TodoItem;
import lombok.Getter;

import java.util.ArrayList;
import java.util.List;

/**
 * 待办事项管理器
 * 负责管理和跟踪待办事项列表，支持添加、更新和渲染待办事项。
 *
 * @author hoppinzq
 * @version 1.0
 */
public class TodoManager {

    /**
     * 待办事项列表
     */
    @Getter
    private final List<TodoItem> todos = new ArrayList<>();

    /**
     * 版本号，每次更新后自增
     */
    @Getter
    private long version = 0;

    /**
     * JSON 映射器，用于解析输入数据
     */
    private final ObjectMapper mapper = new ObjectMapper();

    /**
     * 从 JSON 字符串更新待办事项
     *
     * @param input JSON 格式的待办事项输入
     * @return 更新后的待办事项渲染结果
     */
    public String updateTodos(String input) {
        try {
            TodoInput todoInput = mapper.readValue(input, TodoInput.class);
            return update(todoInput.getTodos());
        } catch (Exception e) {
            return "更新待办事项时出错: " + e.getMessage();
        }
    }

    /**
     * 更新待办事项列表
     * 验证输入的待办事项，检查内容、状态的有效性，并更新列表。
     * 限制最多 20 个待办事项，且同时只能有一个进行中的任务。
     *
     * @param items 待办事项列表
     * @return 更新后的待办事项渲染结果
     * @throws IllegalArgumentException 当输入参数不符合要求时抛出
     */
    public synchronized String update(List<TodoItem> items) {
        if (items == null) {
            items = new ArrayList<>();
        }

        List<TodoItem> validated = new ArrayList<>();
        int inProgressCount = 0;

        for (int i = 0; i < items.size(); i++) {
            TodoItem item = items.get(i);
            String content = item.getContent() != null ? item.getContent().trim() : "";
            String status = item.getStatus() != null ? item.getStatus().toLowerCase() : "pending";
            String activeForm = item.getActiveForm() != null && !item.getActiveForm().trim().isEmpty()
                ? item.getActiveForm().trim()
                : content;

            // 验证内容不能为空
            if (content.isEmpty()) {
                throw new IllegalArgumentException("第 " + i + " 项: 内容不能为空");
            }

            // 验证状态值是否有效
            if (!List.of("pending", "in_progress", "completed").contains(status)) {
                throw new IllegalArgumentException("第 " + i + " 项: 无效的状态 '" + status + "'");
            }

            if (activeForm.isEmpty()) {
                activeForm = content;
            }

            // 统计进行中的任务数量
            if ("in_progress".equals(status)) {
                inProgressCount++;
            }

            item.setContent(content);
            item.setStatus(status);
            item.setActiveForm(activeForm);
            validated.add(item);
        }

        // 限制最多 20 个待办事项
        if (validated.size() > 20) {
            throw new IllegalArgumentException("最多支持 20 个待办事项");
        }

        // 限制同时只能有一个进行中的任务
        if (inProgressCount > 1) {
            throw new IllegalArgumentException("同时只能有一个进行中的任务");
        }

        this.todos.clear();
        this.todos.addAll(validated);
        this.version++;
        return render();
    }

    /**
     * 渲染待办事项列表为字符串
     * <p>
     * 使用不同符号标识不同状态的待办事项：
     * <ul>
     * <li>[ ] - 待处理</li>
     * <li>[>] - 进行中</li>
     * <li>[x] - 已完成</li>
     * </ul>
     * </p>
     *
     * @return 渲染后的待办事项字符串
     */
    public synchronized String render() {
        if (todos.isEmpty()) {
            return "暂无待办事项。";
        }

        StringBuilder sb = new StringBuilder();
        for (TodoItem item : todos) {
            String mark = "[?]";
            if ("completed".equals(item.getStatus())) {
                mark = "[x]";
            } else if ("in_progress".equals(item.getStatus())) {
                mark = "[>]";
            } else if ("pending".equals(item.getStatus())) {
                mark = "[ ]";
            }

            String suffix = "in_progress".equals(item.getStatus())
                ? " <- " + item.getActiveForm()
                : "";
            sb.append(String.format("%s %s%s%n", mark, item.getContent(), suffix));
        }

        long done = todos.stream().filter(t -> "completed".equals(t.getStatus())).count();
        sb.append(String.format("%n(%d/%d 已完成)", done, todos.size()));
        return sb.toString();
    }

    /**
     * 检查是否有未完成的待办事项
     *
     * @return 如果存在未完成的待办事项返回 true，否则返回 false
     */
    public synchronized boolean hasOpenItems() {
        return todos.stream().anyMatch(t -> !"completed".equals(t.getStatus()));
    }
}

package com.hoppinzq.agent.tool.skill;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static com.hoppinzq.agent.constant.AIConstants.SKILL_PATH;

public class SkillLoader {
    private final Map<String, String> skills = new LinkedHashMap<>();

    public SkillLoader() {
        loadSkills();
    }

    private void loadSkills() {
        try {
            URL resourceUrl = getClass().getClassLoader().getResource(SKILL_PATH);
            if (resourceUrl == null) {
                return;
            }

            String protocol = resourceUrl.getProtocol();
            if ("file".equals(protocol)) {
                loadSkillsFromFileSystem(resourceUrl);
            } else if ("jar".equals(protocol)) {
                loadSkillsFromJar(resourceUrl);
            }
        } catch (IOException | URISyntaxException e) {
            e.printStackTrace();
        }
    }

    private void loadSkillsFromFileSystem(URL resourceUrl) throws IOException, URISyntaxException {
        Path skillsPath = Paths.get(resourceUrl.toURI());
        try (Stream<Path> stream = Files.walk(skillsPath)) {
            stream.filter(p -> p.getFileName().toString().equals("SKILL.md"))
                    .forEach(this::parseSkill);
        }
    }

    private void loadSkillsFromJar(URL resourceUrl) throws IOException, URISyntaxException {
        String jarPath = resourceUrl.getPath().substring(5, resourceUrl.getPath().indexOf("!"));
        try (JarFile jarFile = new JarFile(jarPath)) {
            Enumeration<JarEntry> entries = jarFile.entries();
            while (entries.hasMoreElements()) {
                JarEntry entry = entries.nextElement();
                String entryName = entry.getName();
                if (entryName.startsWith(SKILL_PATH) && entryName.endsWith("SKILL.md")) {
                    try (InputStream is = jarFile.getInputStream(entry)) {
                        String content = new BufferedReader(new InputStreamReader(is))
                                .lines()
                                .collect(Collectors.joining("\n"));
                        parseSkillContent(entryName, content);
                    }
                }
            }
        }
    }

    private void parseSkill(Path path) {
        try {
            String content = Files.readString(path);
            String skillName = path.getParent().getFileName().toString();
            parseSkillContent(skillName, content);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void parseSkillContent(String entryName, String content) {
        Pattern pattern = Pattern.compile("^---\\r?\\n(.*?)\\r?\\n---\\r?\\n(.*)", Pattern.DOTALL);
        Matcher matcher = pattern.matcher(content);

        String name = entryName;
        if (entryName.contains("/")) {
            int lastSlash = entryName.lastIndexOf("/");
            if (entryName.endsWith("/SKILL.md")) {
                name = entryName.substring(entryName.lastIndexOf("/", lastSlash - 1) + 1, lastSlash);
            } else {
                name = entryName.substring(0, entryName.indexOf("/"));
            }
        }

        String description = "";
        String body = content;

        if (matcher.find()) {
            String meta = matcher.group(1);
            body = matcher.group(2).trim();
            
            for (String line : meta.split("\\r?\\n")) {
                if (line.contains(":")) {
                    String[] parts = line.split(":", 2);
                    if (parts[0].trim().equals("name")) {
                        name = parts[1].trim();
                    } else if (parts[0].trim().equals("description")) {
                        description = parts[1].trim();
                    }
                }
            }
        }
        
        String escapedName = name.replace("\"", "&quot;");
        String escapedDesc = description.replace("\"", "&quot;");
        skills.put(name, String.format("<skill name=\"%s\" description=\"%s\">\n%s\n</skill>", escapedName, escapedDesc, body));
    }

    public String getSkill(String skillName) {
        if (!skills.containsKey(skillName)) {
            return "错误：未知技能 '" + skillName + "'。可用技能：" + String.join(", ", skills.keySet());
        }
        return skills.get(skillName);
    }

    public String getDescriptions() {
        if (skills.isEmpty()) return "（无可用技能）";
        StringBuilder sb = new StringBuilder();
        skills.forEach((name, body) -> {
            String desc = "-";
            Matcher m = Pattern.compile("description=\"([^\"]*)\"").matcher(body);
            if (m.find()) {
                desc = m.group(1).replace("&quot;", "\"");
            }
            sb.append(String.format("- %s: %s\n", name, desc));
        });
        return sb.toString().trim();
    }

    public List<String> getAvailableSkills() {
        return new ArrayList<>(skills.keySet());
    }
}

package com.hoppinzq.agent.tool.util;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * 完整的文件排除工具类，用于判断给定的文件路径是否应该被排除
 * @author deepseek
 */
public class FileExclusionHelper {
    private final Set<String> excludedDirs;
    private final Set<Pattern> excludedFilePatterns;

    public FileExclusionHelper(Set<String> excludedDirs, Set<String> filePatterns) {
        this.excludedDirs = excludedDirs;
        this.excludedFilePatterns = compilePatterns(filePatterns);
    }

    private Set<Pattern> compilePatterns(Set<String> wildcardPatterns) {
        Set<Pattern> patterns = new HashSet<>();
        for (String wildcard : wildcardPatterns) {
            patterns.add(compileWildcardToPattern(wildcard));
        }
        return patterns;
    }

    private Pattern compileWildcardToPattern(String wildcard) {
        // 将路径分隔符统一为 /
        String normalized = wildcard.replace("\\", "/");
        
        StringBuilder regex = new StringBuilder();
        regex.append("^");
        
        String[] parts = normalized.split("/");
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) {
                regex.append("/");
            }
            
            String part = parts[i];
            if ("**".equals(part)) {
                regex.append(".*");
            } else {
                // 转义特殊字符
                part = part.replace(".", "\\.")
                          .replace("+", "\\+")
                          .replace("$", "\\$")
                          .replace("[", "\\[")
                          .replace("]", "\\]")
                          .replace("(", "\\(")
                          .replace(")", "\\)");
                
                // 将 * 替换为 [^/]*
                part = part.replace("*", "[^/]*");
                // 将 ? 替换为 [^/]
                part = part.replace("?", "[^/]");
                
                regex.append(part);
            }
        }
        
        // 如果以 ** 结尾，需要特殊处理
        if (wildcard.endsWith("/**")) {
            regex.append(".*");
        }
        
        regex.append("$");
        
        return Pattern.compile(regex.toString());
    }

    public boolean shouldExclude(String relativePathStr, boolean isDirectory) {
        // 统一路径分隔符
        String normalizedPath = relativePathStr.replace("\\", "/");

        // 检查目录排除
        boolean dirExcluded = excludedDirs.stream()
                .anyMatch(excludedDir -> {
                    if (normalizedPath.equals(excludedDir)) {
                        return true; // 完全匹配目录名
                    }
                    if (normalizedPath.startsWith(excludedDir + "/")) {
                        return true; // 路径以排除目录开头
                    }
                    if (normalizedPath.contains("/" + excludedDir + "/")) {
                        return true; // 路径中包含排除目录
                    }
                    return false;
                });

        if (dirExcluded) {
            return true;
        }

        // 如果是目录，只检查目录排除规则，不检查文件模式
        if (isDirectory) {
            return false;
        }

        // 检查文件模式排除（只对文件生效）
        for (Pattern pattern : excludedFilePatterns) {
            if (pattern.matcher(normalizedPath).matches()) {
                return true;
            }
        }

        return false;
    }
}

package com.hoppinzq.agent.session;

import com.anthropic.models.messages.MessageParam;
import com.anthropic.models.messages.Usage;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 会话编排器：维护当前 {@code sessionId} 与内存中的消息副本，
 * 在每条消息追加时自动持久化到 {@link SessionStore}。
 * <p>与 agent 解耦：agent 只需在添加消息时调用 {@link #onMessageAppended(MessageParam)}，
 * 启动时调用 {@link #populate(List)} 即可恢复历史。
 *
 * <h3>典型用法</h3>
 * <pre>{@code
 *   SessionManager sm = new SessionManager();
 *   if (args.length > 0 && sm.resume(args[0])) {
 *       System.out.println("已恢复会话 " + sm.getSessionId());
 *   } else {
 *       sm.startNew();
 *       System.out.println("新会话 " + sm.getSessionId());
 *   }
 *   agent.setSessionManager(sm);
 *   sm.populate(agent.getMessageParams());   // 由 ZQAgent.run 启动时自动调用
 *   agent.run();
 * }</pre>
 *
 * @author hoppinzq
 */
public class SessionManager {

    private static final DateTimeFormatter ID_FMT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

    private final SessionStore store;
    private final MessageConverter converter;
    private SessionData sessionData = SessionData.builder().build();
    private String sessionId;

    public SessionManager() {
        this(new SessionStore(), new MessageConverter());
    }

    public SessionManager(SessionStore store, MessageConverter converter) {
        this.store = store;
        this.converter = converter;
    }

    // ============================== 生命周期 ==============================

    /**
     * 创建一个新会话，生成形如 {@code yyyyMMdd-HHmmss-XXXX} 的 ID。
     */
    public String startNew() {
        this.sessionId = generateId();
        this.sessionData = SessionData.builder()
                .messages(new ArrayList<>())
                .usage(new ArrayList<>())
                .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        // 预先落盘一份空文件，便于 listIds 时就能看到
        persist();
        return this.sessionId;
    }

    /**
     * 恢复指定会话。
     *
     * @return 若会话存在且非空返回 {@code true}；否则返回 {@code false}（仍会以该 id 继续会话）
     */
    public boolean resume(String sessionId) {
        this.sessionId = sessionId;
        this.sessionData = store.load(sessionId);

        // 验证会话数据完整性：检查是否有未完成的 tool_use
        if (!this.sessionData.getMessages().isEmpty()) {
            boolean hasIncompleteToolUse = validateMessageIntegrity();
            if (hasIncompleteToolUse) {
                System.out.printf("\u001b[93m警告: 会话 %s 数据不完整，包含未完成的 tool_use，已清理\u001b[0m%n", sessionId);
                // 清理会话数据
                this.sessionData = SessionData.builder()
                        .messages(new ArrayList<>())
                        .usage(new ArrayList<>())
                        .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                        .build();
                // 清空磁盘上的会话文件
                try {
                    store.save(sessionId, this.sessionData);
                } catch (Exception e) {
                    // 忽略保存失败
                }
                return false;
            }
        }

        boolean hasMessages = !this.sessionData.getMessages().isEmpty();
        // 若有历史 usage 数据，打印统计摘要
        if (hasMessages && !sessionData.getUsage().isEmpty()) {
            printSummary();
        }
        return hasMessages;
    }

    /**
     * 验证消息序列的完整性，检查是否有未完成的 tool_use。
     *
     * @return 如果发现未完成的 tool_use 返回 true，否则返回 false
     */
    private boolean validateMessageIntegrity() {
        Set<String> completedToolUses = new HashSet<>();
        Set<String> pendingToolUses = new HashSet<>();

        for (SessionMessage sm : sessionData.getMessages()) {
            if (sm.getBlocks() == null) {
                continue;
            }
            for (SessionBlock block : sm.getBlocks()) {
                if ("tool_use".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.add(toolUseId);
                    }
                } else if ("tool_result".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.remove(toolUseId);
                        completedToolUses.add(toolUseId);
                    }
                }
            }
        }

        // 如果还有未完成的 tool_use，说明数据不完整
        return !pendingToolUses.isEmpty();
    }

    /**
     * 列出所有已存在的会话 ID。
     */
    public List<String> listSessions() {
        return store.listIds();
    }

    // ============================== 与 agent 的桥接 ==============================

    /**
     * 把历史消息回放到 agent 的 messageParams。
     * <p>由 agent 在 run 启动时调用，恢复上下文。
     */
    public void populate(List<MessageParam> out) {
        for (SessionMessage sm : sessionData.getMessages()) {
            out.add(converter.toMessageParam(sm));
        }
    }

    /**
     * 每当 agent 追加一条新消息时调用：转成 {@link SessionMessage} 并落盘。
     */
    public void onMessageAppended(MessageParam param) {
        sessionData.getMessages().add(converter.toSessionMessage(param));
        sessionData.setUpdatedAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
        persist();
    }

    /**
     * 每次调用 LLM 后记录 token 使用情况。
     */
    public void recordUsage(Usage usage) {
        if (usage == null) {
            return;
        }
        TokenUsage tokenUsage = TokenUsage.builder()
                .inputTokens(usage.inputTokens())
                .outputTokens(usage.outputTokens())
                .cacheReadTokens(usage.cacheReadInputTokens().orElse(null))
                .cacheCreationTokens(usage.cacheCreationInputTokens().orElse(null))
                .timestamp(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        sessionData.getUsage().add(tokenUsage);
        persist();
    }

    /**
     * 当前消息数量。
     */
    public int historySize() {
        return sessionData.getMessages().size();
    }

    public String getSessionId() {
        return sessionId;
    }

    // ============================== 内部 ==============================

    private void persist() {
        if (sessionId == null) {
            return;
        }
        store.save(sessionId, sessionData);
    }

    // ============================== Token 统计 ==============================

    /**
     * 本次会话的总 token 消耗（input + output）。
     */
    public long getTotalTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(TokenUsage::getTotalTokens)
                .sum();
    }

    /**
     * 本次会话的输入 token 总和。
     */
    public long getInputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getInputTokens() != null ? u.getInputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的输出 token 总和。
     */
    public long getOutputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getOutputTokens() != null ? u.getOutputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中 token 总和。
     */
    public long getCacheReadTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheReadTokens() != null ? u.getCacheReadTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存创建 token 总和。
     */
    public long getCacheCreationTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheCreationTokens() != null ? u.getCacheCreationTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中率（0-1）。
     * <p>注：Anthropic API 的 {@code input_tokens} 与 {@code cache_read_input_tokens}
     * 是独立统计，后者是额外从 prompt cache 读取的 token 数。
     */
    public double getCacheHitRate() {
        long cached = getCacheReadTokens();
        long input = getInputTokens();
        long totalInput = cached + input;
        if (totalInput == 0) {
            return 0.0;
        }
        return (double) cached / totalInput;
    }

    /**
     * 本次会话的 LLM 调用次数。
     */
    public int getCallCount() {
        return sessionData.getUsage().size();
    }

    /**
     * 获取本次会话的 token 使用明细（只读）。
     */
    public List<TokenUsage> getUsageList() {
        return new ArrayList<>(sessionData.getUsage());
    }

    /**
     * 打印本次会话的 token 统计摘要。
     */
    public void printSummary() {
        System.out.printf("\u001b[90m========== 会话 %s 的 token 统计 ==========\u001b[0m%n", sessionId);
        System.out.printf("\u001b[90m调用次数\u001b[0m: %d%n", getCallCount());
        System.out.printf("\u001b[90m输入 tokens\u001b[0m: %,d%n", getInputTokens());
        System.out.printf("\u001b[90m输出 tokens\u001b[0m: %,d%n", getOutputTokens());
        System.out.printf("\u001b[90m缓存命中 tokens\u001b[0m: %,d%n", getCacheReadTokens());
        System.out.printf("\u001b[90m缓存创建 tokens\u001b[0m: %,d%n", getCacheCreationTokens());
        System.out.printf("\u001b[90m总计 tokens\u001b[0m: %,d%n", getTotalTokens());
        if (getInputTokens() > 0) {
            System.out.printf("\u001b[90m缓存命中率\u001b[0m: %.1f%%%n", getCacheHitRate() * 100);
        }
        System.out.println();
    }

    private String generateId() {
        String time = LocalDateTime.now().format(ID_FMT);
        String rand = Integer.toHexString(ThreadLocalRandom.current().nextInt(0x1000, 0x10000));
        return time + "-" + rand;
    }
}

